}

.resource-card:hover { transform: translateY(-4px); }

.resource-card h3 { font-size: 1.1rem; margin-bottom: 12px; }

.resource-card .resource-link {
  font-weight: 600; font-size: 0.875rem; color: var(--burgundy);
}

.resource-card .resource-link::after { content: ' →'; }

@media (max-width: 768px) { .resources-grid { grid-template-columns: 1fr; } }

/* ===== Product Demo ===== */
.demo-accordion { max-width: 900px; margin: 0 auto; }

.demo-header {
  width: 100%; padding: 20px 24px;
  background: var(--gray-100); border-radius: var(--radius-md);
