  font-weight: 700; font-size: 1.05rem; text-align: left;
  transition: background var(--transition);
}

.demo-header:hover { background: var(--gray-200); }

.demo-header .arrow {
  font-size: 1.2rem; transition: transform var(--transition);
}

.demo-content {
  max-height: 0; overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.demo-accordion.open .demo-content {
  max-height: 500px; padding: 24px;
}

.demo-accordion.open .demo-header .arrow { transform: rotate(45deg); }
.demo-accordion.open .demo-header { background: var(--accent); color: var(--black); }

.demo-mock {
  background: var(--gray-50); border-radius: var(--radius-md);
  padding: 32px; border: 1px solid var(--gray-200);
  display: flex; flex-direction: column; gap: 16px;
}

.demo-mock-row {
  display: flex; gap: 12px; align-items: center;
}

.demo-mock-bar {
  height: 12px; border-radius: 6px; background: var(--gray-200);
}

.demo-mock-bar.fill { background: var(--accent); }

/* ===== Social Proof ===== */
.social-proof-logos {
  display: flex; justify-content: center; align-items: center; gap: 48px;
  flex-wrap: wrap; padding: 40px 0;
}

.social-proof-logos span {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 700; font-size: 1.5rem; color: var(--gray-400);
}

/* ===== Global Scale Section ===== */
.global-scale {
  display: grid; grid-template-columns: 1fr 1fr; gap: 60px;
  align-items: center;
}

.global-map {
  background: var(--gray-800); border-radius: var(--radius-xl);
  height: 300px; display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}

.global-map .map-dots {
  position: absolute; width: 100%; height: 100%;
  display: flex; flex-wrap: wrap; align-items: center; justify-content: center;
  gap: 24px;
}

.global-map .map-dot {
  width: 6px; height: 6px; background: var(--accent);
  border-radius: 50%; opacity: 0.6;
}

.global-features { display: flex; flex-direction: column; gap: 20px; }

.global-feature {
  display: flex; gap: 16px; align-items: flex-start;
}

.global-feature .gf-icon {
  width: 48px; height: 48px; border-radius: var(--radius-md);
  background: var(--accent); color: var(--black);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.3rem; flex-shrink: 0;
}

.global-feature h4 { font-size: 1rem; margin-bottom: 4px; }
.global-feature p { color: var(--gray-400); font-size: 0.9rem; }

@media (max-width: 768px) {
  .global-scale { grid-template-columns: 1fr; gap: 32px; }
}

/* ===== AI Section ===== */
.ai-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px;
}

.ai-card {
  background: var(--gray-800); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-700);
  transition: transform var(--transition);
}

.ai-card:hover { transform: translateY(-4px); border-color: var(--accent); }

.ai-card .ai-icon { font-size: 2rem; margin-bottom: 16px; }
.ai-card h3 { font-size: 1.1rem; margin-bottom: 8px; color: var(--white); }
.ai-card p { color: var(--gray-400); font-size: 0.9rem; }

@media (max-width: 768px) { .ai-grid { grid-template-columns: 1fr; } }

/* ===== Coaching Feature Cards (4-col) ===== */
.coaching-features-grid {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px;
}

.coaching-feature-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-200);
  transition: transform var(--transition);
}

.coaching-feature-card:hover { transform: translateY(-4px); }

.coaching-feature-card h3 { font-size: 1.1rem; margin-bottom: 8px; }
.coaching-feature-card p { color: var(--gray-500); font-size: 0.9rem; }

@media (max-width: 640px) { .coaching-features-grid { grid-template-columns: 1fr; } }

/* ===== Misc ===== */
.text-center { text-align: center; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mt-48 { margin-top: 48px; }

/* Page-specific hero variants */
.hero-page {
  padding: 80px 0 60px;
  background: var(--black);
  color: var(--white);
}

.hero-page .hero-content h1 { color: var(--accent); }

@media (max-width: 640px) {
  .section { padding: 48px 0; }
  .hero-page { padding: 48px 0 32px; }
}

