/* ===== LearnForge Design System ===== */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap');

:root {
  --black: #000000;
  --accent: #E6FF32;
  --accent-dim: #c4d92a;
  --burgundy: #7F2A23;
  --burgundy-light: #9a342b;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.04);
  --transition: 0.2s ease;
  --transition-slow: 0.35s ease;
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== Navigation ===== */
.nav {
  position: sticky; top: 0; z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
}

.nav-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px; height: 72px;
}

.nav-logo {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 800; font-size: 1.5rem;
  display: flex; align-items: center; gap: 8px;
}

.nav-logo .logo-dot {
  width: 10px; height: 10px;
  background: var(--accent);
  border-radius: 50%;
}

.nav-links {
  display: flex; align-items: center; gap: 32px;
}

.nav-links a {
  font-size: 0.9rem; font-weight: 500; color: var(--gray-700);
  transition: color var(--transition);
  position: relative;
  padding: 4px 0;
}

.nav-links a::after {
  content: '';
  position: absolute; bottom: -2px; left: 0;
  width: 0; height: 2px; background: var(--accent);
  transition: width var(--transition);
}

.nav-links a:hover { color: var(--black); }
.nav-links a:hover::after { width: 100%; }

.nav-cta {
  background: var(--accent); color: var(--black);
  padding: 10px 24px; border-radius: 50px;
  font-weight: 700; font-size: 0.875rem;
  transition: background var(--transition), transform var(--transition);
}

.nav-cta:hover { background: var(--accent-dim); transform: translateY(-1px); }

.nav-toggle {
  display: none; flex-direction: column; gap: 5px;
  width: 28px; padding: 4px 0;
}

.nav-toggle span {
  display: block; height: 2.5px; background: var(--black);
  border-radius: 2px; transition: var(--transition);
}

/* ===== Mobile Nav ===== */
@media (max-width: 900px) {
  .nav-links { display: none; }
  .nav-toggle { display: flex; }

  .nav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: 72px; left: 0; right: 0;
    background: var(--white); padding: 24px;
    border-bottom: 1px solid var(--gray-200);
    box-shadow: var(--shadow-lg);
    gap: 16px;
  }
}

/* ===== Hero ===== */
.hero {
  padding: 80px 0 60px;
  background: var(--black);
  color: var(--white);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute; top: -50%; right: -20%;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.08) 0%, transparent 70%);
  border-radius: 50%;
}

.hero .container { position: relative; z-index: 1; }

.hero-content { max-width: 720px; margin: 0 auto; text-align: center; }

.hero h1 { margin-bottom: 20px; }

.hero h1 .highlight {
  background: var(--accent); color: var(--black);
  padding: 2px 12px; border-radius: 4px;
  display: inline-block;
}

.hero p {
  font-size: 1.15rem; color: var(--gray-300);
  max-width: 600px; margin: 0 auto 36px;
}

.hero-buttons {
  display: flex; gap: 16px; justify-content: center; flex-wrap: wrap;
}

.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 14px 32px; border-radius: 50px;
  font-weight: 700; font-size: 1rem;
  transition: all var(--transition);
}

.btn-primary {
  background: var(--accent); color: var(--black);
}

.btn-primary:hover { background: var(--accent-dim); transform: translateY(-2px); }

.btn-outline {
  border: 2px solid var(--white); color: var(--white);
}

.btn-outline:hover { background: var(--white); color: var(--black); }

.btn-burgundy {
  background: var(--burgundy); color: var(--white);
}

.btn-burgundy:hover { background: var(--burgundy-light); transform: translateY(-2px); }

/* Hero Tab Switch */
.hero-tabs {
  margin-top: 48px;
  display: flex; justify-content: center; gap: 4px;
  background: var(--gray-800); border-radius: 50px;
  padding: 4px; max-width: 360px; margin-left: auto; margin-right: auto;
}

.hero-tab {
  padding: 12px 28px; border-radius: 50px;
  font-weight: 600; font-size: 0.9rem;
  color: var(--gray-400);
  transition: all var(--transition);
  flex: 1; text-align: center;
}

.hero-tab.active {
  background: var(--accent); color: var(--black);
}

.hero-preview {
  margin-top: 40px;
  background: var(--gray-800); border-radius: var(--radius-xl);
  padding: 20px; overflow: hidden;
  box-shadow: var(--shadow-xl);
}

.hero-preview-inner {
  background: var(--white); border-radius: var(--radius-lg);
  min-height: 320px; padding: 24px;
  color: var(--black);
  transition: var(--transition-slow);
}

.hero-preview-inner .preview-header {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 700; font-size: 1.1rem;
  margin-bottom: 16px;
  display: flex; align-items: center; gap: 10px;
}

.hero-preview-inner .preview-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--accent);
}

.hero-preview-inner .preview-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px;
}

.hero-preview-inner .preview-card {
  background: var(--gray-50); border-radius: var(--radius-md);
  padding: 16px; border: 1px solid var(--gray-200);
}

.hero-preview-inner .preview-card .pc-title {
  font-weight: 600; font-size: 0.85rem; margin-bottom: 4px;
}

.hero-preview-inner .preview-card .pc-stat {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 800; font-size: 1.5rem; color: var(--accent);
  background: var(--black); display: inline-block; padding: 2px 8px;
  border-radius: 4px;
}

.student-view .preview-grid { grid-template-columns: repeat(2, 1fr); }
.student-view .pc-stat { color: var(--burgundy); background: var(--burgundy); color: var(--white); }

@media (max-width: 640px) {
  .hero-preview-inner .preview-grid { grid-template-columns: 1fr; }
  .hero { padding: 48px 0 40px; }
}

/* ===== Stats Bar ===== */
.stats-bar {
  background: var(--accent); padding: 32px 0;
}

.stats-grid {
  display: flex; justify-content: center; gap: 64px; flex-wrap: wrap;
}

.stat-item { text-align: center; }

.stat-value {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 800; font-size: 2.5rem; color: var(--black);
  line-height: 1;
}

.stat-label {
  font-size: 0.9rem; font-weight: 500; color: var(--gray-700);
  margin-top: 6px;
}

@media (max-width: 640px) {
  .stats-grid { gap: 32px; }
  .stat-value { font-size: 1.8rem; }
}

/* ===== Section ===== */
.section {
  padding: 80px 0;
}

.section-dark { background: var(--black); color: var(--white); }
.section-light { background: var(--gray-50); }
.section-accent { background: var(--accent); }

.section-header {
  text-align: center; max-width: 700px; margin: 0 auto 48px;
}

.section-header h2 { margin-bottom: 16px; }
.section-header p { color: var(--gray-500); font-size: 1.1rem; }

.section-dark .section-header p { color: var(--gray-400); }

/* ===== Product Cards ===== */
.products-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px;
}

.product-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px 24px; box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-200);
  transition: transform var(--transition), box-shadow var(--transition);
  text-align: center;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.product-card .card-icon {
  width: 56px; height: 56px; border-radius: var(--radius-md);
  background: var(--gray-100); margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
}

.product-card h3 { font-size: 1.2rem; margin-bottom: 8px; }
.product-card p { color: var(--gray-500); font-size: 0.9rem; margin-bottom: 16px; }

.card-link {
  font-weight: 600; font-size: 0.875rem; color: var(--burgundy);
  transition: color var(--transition);
}

.card-link::after { content: ' →'; }

.card-link:hover { color: var(--black); }

@media (max-width: 900px) { .products-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 540px) { .products-grid { grid-template-columns: 1fr; } }

/* ===== Why Choose Us Tabs ===== */
.tabs-nav {
  display: flex; gap: 8px; justify-content: center; flex-wrap: wrap;
  margin-bottom: 40px;
}

.tab-btn {
  padding: 12px 24px; border-radius: 50px;
  font-weight: 600; font-size: 0.875rem;
  color: var(--gray-600); background: var(--gray-100);
  transition: all var(--transition);
  border: 2px solid transparent;
}

.tab-btn.active {
  background: var(--accent); color: var(--black);
  border-color: var(--black);
}

.tab-panel { display: none; animation: fadeSlideIn 0.35s ease; }
.tab-panel.active { display: block; }

@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.features-grid {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px;
}

.feature-item {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 16px; background: var(--white); border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
}

.feature-item .check {
  flex-shrink: 0; width: 24px; height: 24px;
  background: var(--accent); border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 0.7rem; font-weight: 700; color: var(--black);
  margin-top: 2px;
}

.feature-item span { font-size: 0.9rem; font-weight: 500; }

@media (max-width: 640px) {
  .features-grid { grid-template-columns: 1fr; }
  .tabs-nav { gap: 6px; }
  .tab-btn { padding: 10px 16px; font-size: 0.8rem; }
}

/* ===== Testimonial Carousel ===== */
.carousel {
  position: relative; overflow: hidden;
}

.carousel-track {
  display: flex; transition: transform 0.4s ease;
}

.carousel-slide {
  min-width: 100%; padding: 0 4px;
}

.testimonial-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 40px; box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-200);
  max-width: 700px; margin: 0 auto;
}

.section-dark .testimonial-card { background: var(--gray-800); border-color: var(--gray-700); }

.testimonial-card .quote-icon {
  font-size: 2.5rem; color: var(--accent);
  font-family: Georgia, serif; line-height: 1; margin-bottom: 12px;
}

.testimonial-card blockquote {
  font-size: 1.15rem; line-height: 1.7; color: var(--gray-700);
  margin-bottom: 20px; font-style: italic;
}

.section-dark .testimonial-card blockquote { color: var(--gray-200); }

.testimonial-card .author {
  display: flex; align-items: center; gap: 12px;
}

.testimonial-card .author-avatar {
  width: 48px; height: 48px; border-radius: 50%;
  background: var(--accent); color: var(--black);
  font-weight: 700; font-size: 1.1rem;
  display: flex; align-items: center; justify-content: center;
}

.testimonial-card .author-name {
  font-weight: 700; font-size: 0.95rem;
}

.testimonial-card .author-badge {
  font-size: 0.8rem; color: var(--accent); font-weight: 600;
}

.section-dark .testimonial-card .author-name { color: var(--white); }
.section-dark .testimonial-card .author-badge { color: var(--accent); }

.carousel-controls {
  display: flex; justify-content: center; gap: 12px; margin-top: 24px;
}

.carousel-btn {
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--gray-100); color: var(--black);
  font-size: 1.2rem; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  transition: all var(--transition);
}

.carousel-btn:hover { background: var(--accent); }

.carousel-dots { display: flex; gap: 8px; justify-content: center; margin-top: 16px; }

.carousel-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--gray-300); transition: all var(--transition);
}

.carousel-dot.active { background: var(--accent); width: 24px; border-radius: 4px; }

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 800px; margin: 0 auto; }

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

